import{_ as p,r as n,o as l,c as o,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Поле Partial - October CMS - 3.x","titleTemplate":false,"description":"UI формы","frontmatter":{"subtitle":"UI формы","shortname":"Partial"},"headers":[{"level":2,"title":"Доступ к переменным","slug":"доступ-к-переменным","link":"#доступ-к-переменным","children":[]},{"level":2,"title":"Использование шаблонов представлений","slug":"использование-шаблонов-представлении","link":"#использование-шаблонов-представлении","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/element/form/ui-partial.md","filePath":"3.x/ru/element/form/ui-partial.md"}'),r={name:"3.x/ru/element/form/ui-partial.md"};function d(u,a,k,h,m,g){const e=n("pre-heading"),t=n("post-heading");return l(),o("div",null,[s(e),a[0]||(a[0]=c("h1",null,"Поле Partial",-1)),s(t),a[1]||(a[1]=i(`<p>UI-элемент <code>partial</code> рендерит частичное представление. Значение <code>path</code> может ссылаться на файл частичного представления, иначе имя поля используется как имя представления.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> field_content
</code></pre></div><p>Поддерживаются следующие <a href="./../form-fields.html">свойства поля</a>.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>path</strong></td><td>путь к <a href="./../../extend/system/views.html">файлу частичного представления</a> или <a href="./../../extend/services/response-view.html">коду шаблона представления</a>, по умолчанию — имя поля с префиксом <strong>field_</strong>.</td></tr></tbody></table></div><p>Когда <code>path</code> задан как неквалифицированное имя файла (имя файла без пути к директории и расширения), исходный путь определяется в директориях модели или контроллера. Следующий пример будет искать файл частичного представления по пути <strong>../models/mymodel/_field_for_content.php</strong> или <strong>../controllers/mycontroller/_field_for_content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> field_for_content
</code></pre></div><p>Вы можете указать полный <code>path</code> для доступа к частичным представлениям вне директорий модели или контроллера. Это может быть полезно для совместного использования частичных представлений между определениями.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> $/acme/blog/partials/_field_content.php
</code></pre></div><h2 id="доступ-к-переменным"><a href="#доступ-к-переменным" class="header-anchor">#</a> Доступ к переменным</h2><p>Следующие переменные доступны внутри частичного представления при его рендеринге.</p><ul><li><code>$value</code> — текущее значение поля, если найдено.</li><li><code>$model</code> — <a href="./../../extend/system/models.html">модель</a>, используемая для поля.</li><li><code>$field</code> — сконфигурированный объект класса <code>Backend\\Classes\\FormField</code>.</li></ul><p>Вот пример содержимого файла <strong>_field_content.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">is_active</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$field</span><span class="token operator">-&gt;</span><span class="token property">label</span> <span class="token delimiter important">?&gt;</span></span> is active<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="использование-шаблонов-представлении"><a href="#использование-шаблонов-представлении" class="header-anchor">#</a> Использование шаблонов представлений</h2><p>Вы можете передать код шаблона представления в <code>path</code> для доступа к шаблонам сервиса представлений внутри плагина. Следующий код будет найден по пути <strong>plugins/acme/blog/views/formfields/content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> acme.blog<span class="token punctuation">:</span><span class="token punctuation">:</span>formfields.content
</code></pre></div><p>Вы также можете разместить частичное представление в директории приложения, например, <strong>app/views/formfields/content.php</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> app<span class="token punctuation">:</span><span class="token punctuation">:</span>formfields.content
</code></pre></div><div class="custom-block tip"><p>Путь должен содержать символы <code>::</code> для активации сервиса представлений.</p></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./ui-hint.html">UI формы Hint</a></li><li><a href="./../../extend/system/views.html">Рендеринг представлений контроллера</a></li><li><a href="./../../extend/services/response-view.html">Сервис ответов и представлений</a></li></ul></div>`,21))])}const _=p(r,[["render",d]]);export{y as __pageData,_ as default};
